<div class="row g-3"><div class="col-lg-7"><div class="card p-3"><table class="table table-sm"><thead><tr><th>Nama</th><th>Peran</th><th>Status</th><th>Hak akses</th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr><td><?= e($r->full_name) ?><br><small class="text-muted"><?= e($r->email) ?></small></td><td><?= $r->is_owner ? 'Admin Travel (owner)' : 'Staff' ?></td><td><?= badge($r->tpu_status) ?></td>
